 @BeforeEach void setupSegments(){var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());segmentRepository=new SegmentRepository(jdbc,json);var pa=new PayrollAccess(access,directory,jdbc);segments=proxy(new SegmentService(access,pa,segmentRepository,payRepository,sources,new PayrollCalculationService(time),repository,new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules()),json,jdbc,time));}
