 @Test void twoSegmentsUseMonthlyCpfAndCdacOnceAndMonthEndLeavesNoDuplicate(){
  var p=configs.findProfile(tenant,profile).orElseThrow();var r=new PayrollDtos.Rule("hourly","50","8","44",true,"1.5",List.of());legacyProfile(new PayrollDtos.PayProfile(p.id(),p.companyId(),p.employeeId(),p.employeeName(),p.effectiveFrom(),p.templateId(),p.templateVersion(),r,p.cpf(),p.version()+1,p.payment(),new PayrollDtos.CdacProfile("applicable","Verified"),p.origin()));completed();secondDay();time.at("2026-10-30T01:00:00Z");
  var first=calculate(LocalDate.of(2026,10,28));assertThat(first.calculation().issues()).isEmpty();first=action(first,"confirm");assertThat(first.calculation().delta().gross()).isEqualTo("400.00");assertThat(first.calculation().delta().employeeCpf()).isEqualTo("0.00");
  time.at("2026-11-02T01:00:00Z");var last=calculate(LocalDate.of(2026,10,31));assertThat(last.from()).isEqualTo(LocalDate.of(2026,10,29));assertThat(last.calculation().issues()).isEmpty();assertThat(last.calculation().delta().gross()).isEqualTo("400.00");assertThat(last.calculation().delta().employeeCpf()).isEqualTo("160.00");assertThat(last.calculation().delta().cdac()).isEqualTo("0.00");assertThat(last.calculation().companySdlDelta()).isEqualTo("0.00");
  last=action(last,"confirm");var totals=segments.page(admin,store,company,"2026-10");assertThat(totals.people()).isEqualTo(1);assertThat(totals.settlementCount()).isEqualTo(2);assertThat(totals.formalTotals().gross()).isEqualTo("800.00");assertThat(totals.formalTotals().net()).isEqualTo("639.50");assertThat(totals.formalTotals().sdl()).isEqualTo("2.00");
 }
