 @Test void onlyOneConcurrentConfirmationClaimsIdenticalCoverage()throws Exception{completed();time.at("2026-10-30T01:00:00Z");var one=calculate(LocalDate.of(2026,10,28));var two=calculate(LocalDate.of(2026,10,28));var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var latch=new java.util.concurrent.CountDownLatch(1);var calls=new ArrayList<java.util.concurrent.Future<Boolean>>();for(var d:List.of(one,two))calls.add(pool.submit(()->{latch.await();try{action(d,"confirm");return true;}catch(WorkforceException ex){return false;}}));latch.countDown();int successes=0;for(var c:calls)if(c.get(30,java.util.concurrent.TimeUnit.SECONDS))successes++;assertThat(successes).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from workforce_pay_segment_days where tenant_id=?",Integer.class,tenant)).isEqualTo(28);}finally{pool.shutdownNow();}}
