 @Test void individualSdlPrecisionSurvivesMultipleSettlements(){var old=configs.findProfile(tenant,profile).orElseThrow();legacyProfile(new PayrollDtos.PayProfile(old.id(),old.companyId(),old.employeeId(),old.employeeName(),old.effectiveFrom(),old.templateId(),old.templateVersion(),new PayrollDtos.Rule("hourly","117.20","8","44",false,"1.5",List.of()),old.cpf(),2,old.payment(),old.cdac(),old.origin()));completed();secondDay();time.at("2026-10-30T01:00:00Z");var first=action(calculate(LocalDate.of(2026,10,28)),"confirm");assertThat(new java.math.BigDecimal(first.calculation().delta().sdl())).isEqualByComparingTo("2.344");time.at("2026-11-02T01:00:00Z");var next=calculate(LocalDate.of(2026,10,31));assertThat(next.calculation().issues()).isEmpty();assertThat(new java.math.BigDecimal(next.calculation().delta().sdl())).isEqualByComparingTo("2.344");}
 @Test void weeklyOvertimeThresholdContinuesAcrossTheSettlementCutoff(){var old=configs.findProfile(tenant,profile).orElseThrow();legacyProfile(new PayrollDtos.PayProfile(old.id(),old.companyId(),old.employeeId(),old.employeeName(),old.effectiveFrom(),old.templateId(),old.templateVersion(),new PayrollDtos.Rule("hourly","100","8","8",true,"1.5",List.of()),old.cpf(),2,old.payment(),old.cdac(),old.origin()));completed();secondDay();time.at("2026-10-30T01:00:00Z");var first=action(calculate(LocalDate.of(2026,10,28)),"confirm");assertThat(first.calculation().delta().gross()).isEqualTo("800.00");time.at("2026-11-02T01:00:00Z");var next=calculate(LocalDate.of(2026,10,31));assertThat(next.calculation().issues()).isEmpty();assertThat(next.calculation().delta().overtime()).isEqualTo("1200.00");assertThat(next.calculation().delta().basic()).isEqualTo("0.00");assertThat(next.calculation().delta().gross()).isEqualTo("1200.00");}
 @Test void unsettledLaterWorkCannotBeApprovedAsAnOmittedWageOfSettledPrefix(){completed();secondDay();time.at("2026-10-30T01:00:00Z");action(calculate(LocalDate.of(2026,10,28)),"confirm");var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());var resolver=new com.rpb.reservation.workforce.payroll.supplemental.SupplementalSourceResolver(jdbc,json,time);var original=resolver.source(tenant,company,employee,YearMonth.of(2026,10));var item=new PayrollDtos.Item("Later unpaid work","wage_event","800.00",null,UUID.randomUUID(),null,new WageEvents.Evidence(UUID.randomUUID(),"omitted_wages","OW",LocalDate.of(2026,10,29),LocalDate.of(2026,10,29),null,LocalDate.of(2026,10,30),"2026-10","2026-10","Synthetic later work","Ordinary monthly wage"));var p=new com.rpb.reservation.workforce.payroll.supplemental.SupplementalDtos.Proposal(UUID.randomUUID(),"2026-10","2026-10",original.source(),List.of(item),"Must settle as the later segment");assertThatThrownBy(()->resolver.validate(tenant,company,employee,p)).hasMessage("SEGMENT_SUPPLEMENT_RANGE_UNSETTLED");var award=new PayrollDtos.Item("Annual award","wage_event","100.00",null,UUID.randomUUID(),null,new WageEvents.Evidence(UUID.randomUUID(),"bonus","AW",LocalDate.of(2026,9,1),LocalDate.of(2026,10,28),null,LocalDate.of(2026,10,30),"2026-10","2026-10","Synthetic AW","Multi-month service"));var aw=new com.rpb.reservation.workforce.payroll.supplemental.SupplementalDtos.Proposal(UUID.randomUUID(),"2026-10","2026-10",original.source(),List.of(award),"Cannot lock out remaining ordinary wages");assertThatThrownBy(()->resolver.validate(tenant,company,employee,aw)).hasMessage("SEGMENT_AW_REQUIRES_FINAL_RANGE");assertThatThrownBy(()->approveTest(new com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.Write(0L,company,employee,LocalDate.of(2026,10,30),null,null,List.of(),null,"Unsettled later work",null,List.of(p)))).hasMessage("SEGMENT_SUPPLEMENT_RANGE_UNSETTLED");}
 @Test void employmentBeginningAfterCutoffCannotCreateFormalZeroFacts(){time.at("2026-10-30T01:00:00Z");var person=UUID.randomUUID();employees.save(admin,store,person,new WorkforceDtos.EmployeeWrite(0L,"FUTURE001","Future start","","","Service",LocalDate.of(2026,10,27),null,"active",company,LocalDate.of(2026,10,27),store,List.of(store,sibling),null,null,null));var old=configs.findProfile(tenant,profile).orElseThrow();legacyProfile(new PayrollDtos.PayProfile(UUID.randomUUID(),company,person,"Legacy dated profile",LocalDate.of(2026,10,1),template,1,old.rule(),old.cpf(),1));assertThatThrownBy(()->segments.save(admin,store,UUID.randomUUID(),new Write(0L,company,person,"2026-10",LocalDate.of(2026,10,26),null,null,true,false,"Not yet employed in this range"))).hasMessage("SEGMENT_EMPLOYMENT_MISSING");}
